const student = $input.first().json.body || $input.first().json;

const systemPrompt = `You are an expert AI Career Advisor & Technical Evaluator. Analyze student profiles and output structured JSON response with skill gap analysis, recommended role, 4-week roadmap, and target skills.`;

const userPrompt = `Student Profile:
Name: ${student.fullName}
Degree: ${student.degree}
Target Goal: ${student.targetGoal}
Current Skills: ${student.currentSkills}
Weekly Time: ${student.weeklyTime}

Provide structured analysis in JSON format with keys:
1. recommendedRole
2. skillGap (array of 3-5 missing skills)
3. week1Roadmap
4. week2Roadmap
5. week3Roadmap
6. week4Roadmap
7. topProjectIdea`;

return [{
  json: {
    student,
    systemPrompt,
    userPrompt
  }
}];

const inputData = $input.all();
const rawStudent = $('Construct_AI_Prompts').first().json.student;
let aiText = '';

try {
  aiText = inputData[0].json.message.content;
} catch (e) {
  aiText = JSON.stringify({
    recommendedRole: rawStudent.targetGoal,
    skillGap: ['Advanced Frameworks', 'Production Deployment', 'API Testing'],
    week1Roadmap: 'Master core concepts and foundational syntax.',
    week2Roadmap: 'Build hands-on projects and understand APIs.',
    week3Roadmap: 'Learn database optimization & backend routing.',
    week4Roadmap: 'Deploy capstone app to cloud (Vercel/AWS) and update portfolio.',
    topProjectIdea: 'Full-Stack Dashboard with Authentication and AI Integration'
  });
}

let parsed = {};
try {
  parsed = JSON.parse(aiText);
} catch (err) {
  parsed = {
    recommendedRole: rawStudent.targetGoal,
    skillGap: ['Advanced Frameworks', 'Cloud Deployment', 'Database Modeling'],
    week1Roadmap: 'Week 1: Deep dive into core language & architecture',
    week2Roadmap: 'Week 2: Backend APIs, Webhooks, and state management',
    week3Roadmap: 'Week 3: Database design, ORM, and Async execution',
    week4Roadmap: 'Week 4: Cloud deployment, CI/CD pipeline, and Portfolio build',
    topProjectIdea: 'AI-Powered Automation Portal for Enterprise Workflows'
  };
}

return [{
  json: {
    ...rawStudent,
    aiAnalysis: parsed,
    analyzedAt: new Date().toISOString()
  }
}];
